package repotest

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"github.com/netwizd/agp/internal/repository"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"
)

// NativeInput names the actual unsigned build and corpus evidence used to
// create an ephemeral TEST-ONLY repository. The fresh keys generated by Native
// must never be installed as production trust material.
type NativeInput struct {
	BundlePath   string
	EvidencePath string
	RendererPath string
	HarnessPath  string
	CorpusPath   string
}

type nativeChecksum struct {
	SHA256 string `json:"sha256"`
	Length int64  `json:"length"`
}
type nativeTuple struct {
	Nginx       string `json:"nginx"`
	ModSecurity string `json:"modsecurity"`
	Connector   string `json:"connector"`
	CRS         string `json:"crs"`
}
type nativeUserspace struct {
	ID           string `json:"id"`
	VersionID    string `json:"versionId"`
	ImageVersion string `json:"imageVersion"`
}
type nativeBuild struct {
	Format                 string          `json:"format"`
	Platform               string          `json:"platform"`
	Tuple                  nativeTuple     `json:"tuple"`
	Userspace              nativeUserspace `json:"userspace"`
	PublicationAuthority   bool            `json:"publicationAuthority"`
	NginxVersionOutput     string          `json:"nginxVersionOutput"`
	NginxConfigure         []string        `json:"nginxConfigure"`
	ModSecurityConfigure   []string        `json:"modsecurityConfigure"`
	LockDigest             string          `json:"lockDigest"`
	LicenseInventoryDigest string          `json:"licenseInventoryDigest"`
	Sources                json.RawMessage `json:"sources"`
	Dependencies           json.RawMessage `json:"dependencies"`
}
type nativeRawEvidence struct {
	Format               string                    `json:"format"`
	PublicationAuthority *bool                     `json:"publicationAuthority"`
	Platform             repository.Platform       `json:"platform"`
	Tuple                nativeTuple               `json:"tuple"`
	Userspace            nativeUserspace           `json:"userspace"`
	HostKernel           string                    `json:"hostKernel"`
	StartedAt            time.Time                 `json:"startedAt"`
	CompletedAt          time.Time                 `json:"completedAt"`
	Checks               []json.RawMessage         `json:"checks"`
	Passed               bool                      `json:"passed"`
	Error                json.RawMessage           `json:"error"`
	HarnessDigest        string                    `json:"harnessDigest"`
	CorpusDigest         string                    `json:"corpusDigest"`
	BuildDigest          string                    `json:"buildDigest"`
	ChecksumsDigest      string                    `json:"checksumsDigest"`
	NginxVersionOutput   string                    `json:"nginxVersionOutput"`
	LoaderVersion        string                    `json:"loaderVersion"`
	PolicyRenderer       nativeRenderer            `json:"policyRenderer"`
	ArtifactChecksums    map[string]nativeChecksum `json:"artifactChecksums"`
}
type nativeRenderer struct {
	Implementation string `json:"implementation"`
	Digest         string `json:"digest"`
}
type nativeLicense struct {
	SourcePackage        string   `json:"sourcePackage"`
	SourceVersion        string   `json:"sourceVersion"`
	SourceArtifactDigest string   `json:"sourceArtifactDigest"`
	License              string   `json:"license"`
	NoticePaths          []string `json:"noticePaths"`
	Digest               string   `json:"digest"`
}
type nativeLicenses struct {
	Format string                   `json:"format"`
	Files  map[string]nativeLicense `json:"files"`
}

var nativePathPattern = regexp.MustCompile(`^[A-Za-z0-9/_.+-]{1,256}$`)
var nativeHashPattern = regexp.MustCompile(`^[0-9a-f]{64}$`)

func nativeError(reason string) error { return fmt.Errorf("TEST-ONLY native repository: %s", reason) }
func nativePath(name string) bool {
	return nativePathPattern.MatchString(name) && !strings.HasPrefix(name, "/") && path.Clean(name) == name && name != "." && name != ".." && !strings.HasPrefix(name, "../")
}
func nativeAbsolute(name string) error {
	if !filepath.IsAbs(name) || filepath.Clean(name) != name {
		return nativeError("input paths must be absolute and clean")
	}
	real, e := filepath.EvalSymlinks(name)
	if e != nil {
		return e
	}
	if real != name {
		return nativeError("input paths must not contain symlinks")
	}
	return nil
}
func nativeRead(name string, limit int64) ([]byte, error) {
	if e := nativeAbsolute(name); e != nil {
		return nil, e
	}
	return repository.DirectoryReader(filepath.Dir(name))(filepath.Base(name), limit)
}
func nativeJSON(raw []byte, out any) error {
	if e := repository.ValidateMetadataJSON(raw); e != nil {
		return e
	}
	return json.Unmarshal(raw, out)
}
func nativeRuntime(name string) bool {
	return strings.HasPrefix(name, "bin/") || strings.HasPrefix(name, "modules/") || strings.HasPrefix(name, "lib/") || strings.HasPrefix(name, "share/")
}
func nativeEvidenceRuntime(name string) bool {
	return strings.HasPrefix(name, "bin/") || strings.HasPrefix(name, "modules/") || strings.HasPrefix(name, "lib/") || strings.HasPrefix(name, "share/crs/") || strings.HasPrefix(name, "share/modsecurity/")
}

// Native preserves the actual runtime bytes, source records, notices, measured
// checks and wall-clock timestamps. Signing establishes isolated lab authority;
// it never upgrades an operator catalog or fabricates native evidence.
func Native(ctx context.Context, in NativeInput) (*Fixture, error) {
	if e := ctx.Err(); e != nil {
		return nil, e
	}
	if e := nativeAbsolute(in.BundlePath); e != nil {
		return nil, e
	}
	read := repository.DirectoryReader(in.BundlePath)
	buildRaw, e := read("build.json", repository.MaxMetadataBytes)
	if e != nil {
		return nil, e
	}
	checksumsRaw, e := read("checksums.json", repository.MaxMetadataBytes)
	if e != nil {
		return nil, e
	}
	licensesRaw, e := read("licenses.json", repository.MaxMetadataBytes)
	if e != nil {
		return nil, e
	}
	raw, e := nativeRead(in.EvidencePath, repository.MaxMetadataBytes)
	if e != nil {
		return nil, e
	}
	harness, e := nativeRead(in.HarnessPath, repository.MaxMetadataBytes)
	if e != nil {
		return nil, e
	}
	corpusRaw, e := nativeRead(in.CorpusPath, repository.MaxMetadataBytes)
	if e != nil {
		return nil, e
	}
	renderer, e := nativeRead(in.RendererPath, repository.MaxArtifactBytes)
	if e != nil {
		return nil, e
	}
	var build nativeBuild
	var checksums map[string]nativeChecksum
	var licenses nativeLicenses
	var report nativeRawEvidence
	for _, d := range []struct {
		raw []byte
		out any
	}{{buildRaw, &build}, {checksumsRaw, &checksums}, {licensesRaw, &licenses}, {raw, &report}} {
		if e = nativeJSON(d.raw, d.out); e != nil {
			return nil, e
		}
	}
	expectedTuple := nativeTuple{"1.30.8", "3.0.17", "1.0.4", "4.30.0"}
	expectedPlatform := repository.Platform{OS: "ubuntu", OSVersion: "24.04", Arch: "amd64"}
	now := time.Now().UTC().Truncate(time.Microsecond)
	if report.Format != "agp.waf-native-evidence/v1" || report.PublicationAuthority == nil || *report.PublicationAuthority || !report.Passed || !bytes.Equal(bytes.TrimSpace(report.Error), []byte("null")) || report.Platform != expectedPlatform || report.Tuple != expectedTuple || report.HostKernel == "" || report.StartedAt.IsZero() || report.CompletedAt.Before(report.StartedAt) || report.CompletedAt.After(now) {
		return nil, nativeError("native report did not pass on the exact platform/tuple")
	}
	if build.Format != "agp.waf-native-build/v1" || build.PublicationAuthority || build.Platform != "ubuntu24.04amd64" || build.Tuple != expectedTuple || build.Userspace.ID != "ubuntu" || build.Userspace.VersionID != "24.04" || build.Userspace != report.Userspace || !strings.Contains(build.NginxVersionOutput, "nginx/1.30.8") || build.NginxVersionOutput != report.NginxVersionOutput || !strings.Contains(report.LoaderVersion, "2.39") || len(build.NginxConfigure) == 0 || len(build.ModSecurityConfigure) == 0 {
		return nil, nativeError("build provenance or actual executable version mismatch")
	}
	if !strings.Contains(build.NginxVersionOutput, "configure arguments: "+strings.Join(build.NginxConfigure, " ")) || !bytes.HasPrefix(renderer, []byte{0x7f, 'E', 'L', 'F', 2, 1}) {
		return nil, nativeError("actual build flags or renderer ELF mismatch")
	}
	if report.BuildDigest != repository.Hash(buildRaw) || report.ChecksumsDigest != repository.Hash(checksumsRaw) || report.HarnessDigest != repository.Hash(harness) || report.CorpusDigest != repository.Hash(corpusRaw) || report.PolicyRenderer.Implementation != "agpctl-waf-render" || report.PolicyRenderer.Digest != repository.Hash(renderer) || build.LicenseInventoryDigest != repository.Hash(licensesRaw) {
		return nil, nativeError("report source, renderer or license digest mismatch")
	}
	checks, e := nativeChecks(corpusRaw, report.Checks)
	if e != nil {
		return nil, e
	}
	if len(checksums) == 0 || len(checksums) > 950 {
		return nil, nativeError("bundle file count")
	}
	objects := make(map[string][]byte, len(checksums))
	var total int64
	for name, checksum := range checksums {
		if e = ctx.Err(); e != nil {
			return nil, e
		}
		if !nativePath(name) || name == "checksums.json" || !nativeHashPattern.MatchString(checksum.SHA256) || checksum.Length < 1 || checksum.Length > repository.MaxArtifactBytes {
			return nil, nativeError("bundle checksum contract")
		}
		total += checksum.Length
		if total > repository.MaxReleaseBytes-(128<<20) {
			return nil, nativeError("bundle byte budget")
		}
		data, err := read(name, checksum.Length)
		if err != nil {
			return nil, err
		}
		if int64(len(data)) != checksum.Length || repository.Hash(data) != "sha256:"+checksum.SHA256 {
			return nil, nativeError("runtime/provenance file checksum mismatch: " + name)
		}
		objects[name] = data
	}
	if e = filepath.WalkDir(in.BundlePath, func(name string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if e := ctx.Err(); e != nil {
			return e
		}
		if d.Type()&os.ModeSymlink != 0 {
			return nativeError("bundle symlink")
		}
		if d.IsDir() {
			return nil
		}
		if !d.Type().IsRegular() {
			return nativeError("non-regular bundle member")
		}
		rel, err := filepath.Rel(in.BundlePath, name)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if rel != "checksums.json" && objects[rel] == nil {
			return nativeError("unchecked bundle member: " + rel)
		}
		return nil
	}); e != nil {
		return nil, e
	}
	if !bytes.Equal(objects["build.json"], buildRaw) || !bytes.Equal(objects["licenses.json"], licensesRaw) {
		return nil, nativeError("unsealed build/license records")
	}
	for name, checksum := range checksums {
		if nativeEvidenceRuntime(name) {
			if report.ArtifactChecksums[name] != checksum {
				return nil, nativeError("native report runtime checksum mismatch")
			}
		}
	}
	for name, checksum := range report.ArtifactChecksums {
		if !nativeEvidenceRuntime(name) || checksums[name] != checksum {
			return nil, nativeError("unexpected native report runtime member")
		}
	}
	allowedSources, e := nativeSources(build, objects["provenance/waf-native.lock.json"])
	if e != nil {
		return nil, e
	}
	if licenses.Format != "agp.waf-native-license-inventory/v1" {
		return nil, nativeError("license inventory format")
	}
	f := New(now)
	f.Now = now
	f.Manifest.CreatedAt = now
	f.Manifest.ReleaseID = "release_waf_native_test"
	f.Manifest.ExpiresAt = now.Add(24 * time.Hour)
	p := repository.ComponentProfile{APIVersion: "agp.component-profile/v1alpha1", ID: "profile_waf_native_ubuntu24", Platform: expectedPlatform, RulesetVersionID: "crs_4_30_0", LoaderPath: "lib/ld-linux-x86-64.so.2", NginxPath: "bin/nginx", ModulePath: "modules/ngx_http_modsecurity_module.so", UnicodePath: "share/modsecurity/unicode.mapping", RulesPath: "share/crs/rules", Files: []repository.ProfileFile{}}
	if len(objects[p.LoaderPath]) == 0 || len(objects[p.NginxPath]) == 0 || len(objects[p.ModulePath]) == 0 || len(objects[p.UnicodePath]) == 0 {
		return nil, nativeError("required runtime file absent")
	}
	for _, name := range []string{p.LoaderPath, p.NginxPath, p.ModulePath} {
		if !bytes.HasPrefix(objects[name], []byte{0x7f, 'E', 'L', 'F', 2, 1}) {
			return nil, nativeError("runtime component is not little-endian ELF64")
		}
	}
	flags := []string{}
	for _, v := range build.NginxConfigure {
		flags = append(flags, "nginx:"+v)
	}
	for _, v := range build.ModSecurityConfigure {
		flags = append(flags, "modsecurity:"+v)
	}
	if len(flags) > 64 {
		return nil, nativeError("build flag capacity")
	}
	p.Tuple = repository.ComponentTuple{Nginx: expectedTuple.Nginx, Connector: expectedTuple.Connector, LibModSecurity: expectedTuple.ModSecurity, CRS: expectedTuple.CRS, BuildFlags: flags, ABIDigest: repository.Hash(Canonical(struct {
		NginxVersionOutput string `json:"nginxVersionOutput"`
		ModuleDigest       string `json:"moduleDigest"`
	}{build.NginxVersionOutput, repository.Hash(objects[p.ModulePath])}))}
	sbom := repository.SBOM{APIVersion: "agp.sbom/v1alpha1", Files: []repository.SBOMFile{}}
	names := make([]string, 0, len(objects))
	for name := range objects {
		names = append(names, name)
	}
	sort.Strings(names)
	runtimeCount := 0
	for _, name := range names {
		data := objects[name]
		d := f.Add(data, "application/octet-stream")
		if !nativeRuntime(name) {
			continue
		}
		license, ok := licenses.Files[name]
		if !ok || license.Digest != d || license.SourcePackage == "" || license.SourceVersion == "" || !allowedSources[license.SourceArtifactDigest] || license.License == "" || strings.Contains(license.License, "TEST-ONLY") || len(license.NoticePaths) == 0 {
			return nil, nativeError("missing byte-backed license provenance: " + name)
		}
		for _, notice := range license.NoticePaths {
			if !nativePath(notice) || !nativeRuntime(notice) || len(objects[notice]) == 0 {
				return nil, nativeError("license notice outside runtime closure")
			}
		}
		p.Files = append(p.Files, repository.ProfileFile{Path: name, Digest: d})
		sbom.Files = append(sbom.Files, repository.SBOMFile{Path: name, Digest: d, License: license.License})
		runtimeCount++
	}
	if runtimeCount != len(licenses.Files) {
		return nil, nativeError("license inventory does not exactly cover runtime files")
	}
	f.Manifest.CompatibilityProfile = repository.ProfileRef{ID: p.ID, Digest: f.Add(Canonical(p), "application/vnd.agp.component-profile+json")}
	qualification := repository.QualificationEvidence{APIVersion: "agp.waf-qualification/v1alpha1", ProfileDigest: f.Manifest.CompatibilityProfile.Digest, TupleDigest: repository.Hash(Canonical(p.Tuple)), CorpusDigest: f.Add(corpusRaw, "application/vnd.agp.native-corpus+json"), HarnessDigest: f.Add(harness, "text/x-python"), RendererDigest: f.Add(renderer, "application/octet-stream"), NativeReportDigest: f.Add(raw, "application/vnd.agp.waf-native-report+json"), Platform: report.Platform, HostKernel: report.HostKernel, StartedAt: report.StartedAt, CompletedAt: report.CompletedAt, Checks: checks}
	f.Add(checksumsRaw, "application/vnd.agp.native-checksums+json")
	f.Add(Canonical(qualification), "application/vnd.agp.waf-qualification+json")
	f.Manifest.SBOMDigest = f.Add(Canonical(sbom), "application/vnd.agp.sbom+json")
	verified, e := repository.Verify(ctx, f.Anchor, nil, f.Build(1), now)
	if e != nil {
		return nil, e
	}
	if _, e = verified.QualifiedProfile(now); e != nil {
		return nil, e
	}
	return f, nil
}

func nativeChecks(raw []byte, executed []json.RawMessage) ([]repository.QualificationCheck, error) {
	var corpus struct {
		Format string   `json:"format"`
		Cases  []string `json:"cases"`
	}
	if e := nativeJSON(raw, &corpus); e != nil {
		return nil, e
	}
	if corpus.Format != "agp.waf-native-corpus/v1" || len(corpus.Cases) != 25 || len(executed) != 25 {
		return nil, nativeError("all 25 native corpus cases are mandatory")
	}
	expected := map[string]bool{}
	for _, id := range repository.RequiredNativeChecks {
		expected[id] = true
	}
	if len(expected) != 25 {
		return nil, nativeError("unsupported native corpus revision")
	}
	for _, id := range corpus.Cases {
		if !expected[id] {
			return nil, nativeError("corpus case set mismatch")
		}
		delete(expected, id)
	}
	if len(expected) != 0 {
		return nil, nativeError("duplicate or missing corpus case")
	}
	checks := make([]repository.QualificationCheck, 0, 25)
	seen := map[string]bool{}
	for _, data := range executed {
		var c struct {
			ID      string          `json:"id"`
			Passed  bool            `json:"passed"`
			Skipped bool            `json:"skipped"`
			Skip    bool            `json:"skip"`
			Status  json.RawMessage `json:"status"`
		}
		if e := nativeJSON(data, &c); e != nil {
			return nil, e
		}
		if !c.Passed || c.Skip || c.Skipped || seen[c.ID] || !containsCase(corpus.Cases, c.ID) || bytes.Contains(bytes.ToUpper(c.Status), []byte("SKIP")) {
			return nil, nativeError("failed, skipped, duplicate or unknown native check")
		}
		seen[c.ID] = true
		checks = append(checks, repository.QualificationCheck{ID: c.ID, Passed: true})
	}
	return checks, nil
}
func containsCase(ids []string, id string) bool {
	for _, v := range ids {
		if id == v {
			return true
		}
	}
	return false
}
func nativeSources(build nativeBuild, raw []byte) (map[string]bool, error) {
	if len(raw) == 0 || repository.Hash(raw) != build.LockDigest {
		return nil, nativeError("source lock digest mismatch")
	}
	var lock struct {
		Platform             string          `json:"platform"`
		Tuple                nativeTuple     `json:"tuple"`
		NginxConfigure       []string        `json:"nginxConfigure"`
		ModSecurityConfigure []string        `json:"modsecurityConfigure"`
		Sources              json.RawMessage `json:"sources"`
		Packages             json.RawMessage `json:"packages"`
	}
	if e := nativeJSON(raw, &lock); e != nil {
		return nil, e
	}
	if lock.Platform != build.Platform || lock.Tuple != build.Tuple || !bytes.Equal(Canonical(lock.Sources), Canonical(build.Sources)) || !bytes.Equal(Canonical(lock.Packages), Canonical(build.Dependencies)) || !bytes.Equal(Canonical(lock.NginxConfigure), Canonical(build.NginxConfigure)) || !bytes.Equal(Canonical(lock.ModSecurityConfigure), Canonical(build.ModSecurityConfigure)) {
		return nil, nativeError("build inputs differ from the sealed source lock")
	}
	sources := map[string]bool{}
	for _, data := range []json.RawMessage{lock.Sources, lock.Packages} {
		var inputs []struct {
			SHA256 string `json:"sha256"`
			Length int64  `json:"length"`
		}
		if e := json.Unmarshal(data, &inputs); e != nil {
			return nil, e
		}
		if len(inputs) == 0 {
			return nil, nativeError("empty source/dependency lock")
		}
		for _, input := range inputs {
			if !nativeHashPattern.MatchString(input.SHA256) || input.Length < 1 {
				return nil, nativeError("source checksum contract")
			}
			sources["sha256:"+input.SHA256] = true
		}
	}
	return sources, nil
}
